CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS categories(key TEXT PRIMARY KEY, enabled INTEGER NOT NULL DEFAULT 1, sort INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rates_current(
  key TEXT PRIMARY KEY, value REAL, prev REAL, direction TEXT NOT NULL DEFAULT 'flat', received_at REAL, source TEXT);
CREATE TABLE IF NOT EXISTS rate_history(id INTEGER PRIMARY KEY AUTOINCREMENT, key TEXT NOT NULL, value REAL NOT NULL, source TEXT, at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS admin_users(username TEXT PRIMARY KEY, password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS event_log(id INTEGER PRIMARY KEY AUTOINCREMENT, at REAL NOT NULL, level TEXT NOT NULL, message TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pricing(key TEXT PRIMARY KEY, calc TEXT NOT NULL DEFAULT 'direct', purity REAL NOT NULL DEFAULT 100, margin REAL NOT NULL DEFAULT 0);
